package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"time"
)

type correlateThreat struct {
	obj        map[string]interface{}
	ref        time.Time
	actors     []string
	risk       float64
	threatType string
	severity   string
}

type correlateCampaign struct {
	CampaignID         string                   `json:"campaign_id"`
	ThreatCount        int                      `json:"threat_count"`
	ThreatTypes        []string                 `json:"threat_types"`
	SharedActors       []string                 `json:"shared_actors"`
	AllActors          []string                 `json:"all_actors"`
	CombinedRisk       float64                  `json:"combined_risk"`
	DirectLinkCount    int                      `json:"direct_link_count"`
	Cohesion           float64                  `json:"cohesion"`
	PropagationScore   float64                  `json:"propagation_score"`
	MaxSeverity        string                   `json:"max_severity"`
	TimeSpanMinutes    float64                  `json:"time_span_minutes"`
	Earliest           string                   `json:"earliest"`
	Latest             string                   `json:"latest"`
	Threats            []map[string]interface{} `json:"threats"`

	earliestTime  time.Time
	minThreatType string
}

func runCorrelate(args []string) int {
	fs := newFlagSet("correlate")
	timeWindow := fs.Int("time-window", 0, "maximum temporal distance in minutes for two threats to be linkable")
	minCampaignSize := fs.Int("min-campaign-size", 2, "minimum number of threats in a campaign to output")
	if !parseFlags(fs, args) {
		return 1
	}
	if !isFlagSet(fs, "time-window") {
		fmt.Fprintln(os.Stderr, "error: --time-window flag is required")
		return 1
	}

	window := time.Duration(*timeWindow) * time.Minute

	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
	threats := make([]correlateThreat, 0)
	lineNo := 0
	for scanner.Scan() {
		lineNo++
		line := scanner.Text()
		if line == "" {
			continue
		}
		var obj map[string]interface{}
		if err := json.Unmarshal([]byte(line), &obj); err != nil {
			fmt.Fprintf(os.Stderr, "line %d: %v\n", lineNo, err)
			return 2
		}
		ct := correlateThreat{
			obj: obj,
			ref: threatReferenceTime(obj),
		}
		if actors, ok := getStringSlice(obj, "threat_actors"); ok {
			ct.actors = actors
		} else {
			ct.actors = []string{}
		}
		if r, ok := getFloat(obj, "enriched_risk_score"); ok {
			ct.risk = r
		}
		if tt, ok := getString(obj, "threat_type"); ok {
			ct.threatType = tt
		}
		if sev, ok := getString(obj, "ioc_severity"); ok {
			ct.severity = sev
		}
		threats = append(threats, ct)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	n := len(threats)
	linked := make([][]bool, n)
	for i := range linked {
		linked[i] = make([]bool, n)
	}
	for i := 0; i < n; i++ {
		if len(threats[i].actors) == 0 {
			continue
		}
		for j := i + 1; j < n; j++ {
			if len(threats[j].actors) == 0 {
				continue
			}
			if absDuration(threats[i].ref.Sub(threats[j].ref)) <= window && sharedActorCount(threats[i].actors, threats[j].actors) > 0 {
				linked[i][j] = true
				linked[j][i] = true
			}
		}
	}

	visited := make([]bool, n)
	var campaigns []correlateCampaign
	for start := 0; start < n; start++ {
		if visited[start] {
			continue
		}
		queue := []int{start}
		visited[start] = true
		component := []int{start}
		for len(queue) > 0 {
			cur := queue[0]
			queue = queue[1:]
			for next := 0; next < n; next++ {
				if !visited[next] && linked[cur][next] {
					visited[next] = true
					queue = append(queue, next)
					component = append(component, next)
				}
			}
		}
		if len(component) < *minCampaignSize {
			continue
		}
		campaigns = append(campaigns, buildCorrelateCampaign(threats, component, linked))
	}

	sort.SliceStable(campaigns, func(i, j int) bool {
		if !campaigns[i].earliestTime.Equal(campaigns[j].earliestTime) {
			return campaigns[i].earliestTime.Before(campaigns[j].earliestTime)
		}
		return campaigns[i].minThreatType < campaigns[j].minThreatType
	})
	for i := range campaigns {
		campaigns[i].CampaignID = fmt.Sprintf("CAMP-%03d", i+1)
	}

	sort.SliceStable(campaigns, func(i, j int) bool {
		if campaigns[i].CombinedRisk != campaigns[j].CombinedRisk {
			return campaigns[i].CombinedRisk > campaigns[j].CombinedRisk
		}
		if campaigns[i].Cohesion != campaigns[j].Cohesion {
			return campaigns[i].Cohesion > campaigns[j].Cohesion
		}
		return campaigns[i].CampaignID < campaigns[j].CampaignID
	})

	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	enc := json.NewEncoder(w)
	for _, c := range campaigns {
		if err := enc.Encode(c); err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
	}
	return 0
}

func buildCorrelateCampaign(threats []correlateThreat, indices []int, linked [][]bool) correlateCampaign {
	c := correlateCampaign{
		ThreatCount:  len(indices),
		ThreatTypes:  []string{},
		SharedActors: []string{},
		AllActors:    []string{},
		Threats:      []map[string]interface{}{},
	}

