	actorSet := make(map[string]bool)
	for _, idx := range indices {
		typeSet[threats[idx].threatType] = true
		for _, actor := range threats[idx].actors {
			actorSet[actor] = true
		}
	}
	c.ThreatTypes = sortedKeys(typeSet)
	c.AllActors = sortedUniqueStringsFromSet(actorSet)

	if len(indices) > 0 {
		shared := make(map[string]bool)
		for _, actor := range threats[indices[0]].actors {
			shared[actor] = true
		}
		for _, idx := range indices[1:] {
			next := make(map[string]bool)
			for _, actor := range threats[idx].actors {
				if shared[actor] {
					next[actor] = true
				}
			}
			shared = next
		}
		c.SharedActors = sortedUniqueStringsFromSet(shared)
	}

	directLinkCount := 0
	for ii, i := range indices {
		for jj := ii + 1; jj < len(indices); jj++ {
			if linked[i][indices[jj]] {
				directLinkCount++
			}
		}
	}
	c.DirectLinkCount = directLinkCount
	if c.ThreatCount > 1 {
		c.Cohesion = float64(directLinkCount) / (float64(c.ThreatCount*(c.ThreatCount-1)) / 2.0)
	} else {
		c.Cohesion = 0.0
	}

	propagationScore := 0.0
	for ii, i := range indices {
		for jj := ii + 1; jj < len(indices); jj++ {
