	for _, idx := range sortedIndices {
		c.Threats = append(c.Threats, threats[idx].obj)
	}

	return c
}

func sharedActorCount(a, b []string) int {
	set := make(map[string]bool)
	for _, s := range a {
		set[s] = true
	}
	count := 0
	seen := make(map[string]bool)
	for _, s := range b {
		if set[s] && !seen[s] {
			count++
			seen[s] = true
		}
	}
	return count
}

func absDuration(d time.Duration) time.Duration {
	if d < 0 {
		return -d
	}
	return d
}

func correlateSeverityRank(s string) int {
	switch s {
	case "none":
		return 0
	case "low":
		return 1
	case "medium":
		return 2
	case "high":
		return 3
	case "critical":
		return 4
	default:
		return 0
	}
}
